function renderPortfolio() {
  const projects = [
    {id:4, cat:'other',  titleKey:'p5_title', descKey:'p5_desc', longKey:'p5_long', tags:['Linux','Virtualisation','PRTG','Réseau'], icon:''},
    {id:1, cat:'web',    titleKey:'p2_title', descKey:'p2_desc', longKey:'p2_long', tags:['ChipWhisperer','AES','Python','Cryptologie'], icon:''},
    {id:0, cat:'web',    titleKey:'p1_title', descKey:'p1_desc', longKey:'p1_long', tags:['HTML','CSS','JS','Google Sites'], icon:''},
    {id:3, cat:'web',    titleKey:'p4_title', descKey:'p4_desc', longKey:'p4_long', tags:['Arduino','Bluetooth','C','Android'], icon:''},
    {id:2, cat:'design', titleKey:'p3_title', descKey:'p3_desc', longKey:'p3_long', tags:['mySQL','PostgreSQL'], icon:''},
  ];
  window._pfProjects = projects;
  window._pfView = window._pfView || 'list';
  window._pfFilter = window._pfFilter || 'all';
  window._pfSelected = window._pfSelected ?? null;
  pfRenderList();
  document.getElementById('pf-count').textContent = projects.length + ' ' + (t('pf_objects')||'objects');
}


function pfCloseOverlay() {
  const ov = document.getElementById('pf-overlay');
  if(ov) ov.style.display = 'none';
  window._pfSelected = null;
}

function pfFilter(cat) {
  window._pfFilter = cat;
  pfRenderList();
}

function pfSetView(v) {
  window._pfView = v;
  window._pfSelected = null;
  pfRenderList();
}

function pfRenderList() {
  const projects = window._pfProjects || [];
  const list = document.getElementById('pf-list');
  const detail = document.getElementById('pf-detail');
  if(!list) return;
  const isGrid = window._pfView === 'grid';

  if(isGrid) {
    // Grid: full-width tile view, detail shown as overlay panel on top
    list.style.cssText = 'width:100%;border-right:none;display:flex;flex-wrap:wrap;align-content:flex-start;padding:12px;gap:10px;background:#fff;overflow-y:auto';
    detail.style.display = 'none';
    list.innerHTML = projects.map(p=>`
      <div onclick="pfSelect(${p.id})" style="width:140px;border:2px solid #808080;border-top-color:#fff;border-left-color:#fff;padding:10px 8px;cursor:pointer;background:var(--win-gray);text-align:center;transition:background .1s" onmouseover="this.style.background='#d0d8f0'" onmouseout="this.style.background='var(--win-gray)'">
        <div style="font-size:28px">${p.icon}</div>
        <div style="font-size:11px;font-weight:bold;margin-top:5px;line-height:1.3">${t(p.titleKey)}</div>
      </div>`).join('');
  } else {
    // List: left sidebar + right detail panel
    list.style.cssText = 'width:220px;min-width:180px;border-right:2px solid #808080;display:block;overflow-y:auto;background:#fff';
    detail.style.display = 'block';
    list.innerHTML = projects.map(p=>`
      <div onclick="pfSelect(${p.id})" style="display:flex;align-items:center;gap:6px;padding:5px 8px;cursor:pointer;border-bottom:1px solid #e0e0e0;background:${window._pfSelected===p.id?'#000080':'transparent'};color:${window._pfSelected===p.id?'#fff':'inherit'}">
        <span style="font-size:18px">${p.icon}</span>
        <div style="font-size:11px;font-weight:bold">${t(p.titleKey)}</div>
      </div>`).join('');
  }
}

function pfSelect(id) {
  window._pfSelected = id;
  const isGrid = window._pfView === 'grid';
  if(!isGrid) pfRenderList();
  const p = (window._pfProjects||[]).find(x=>x.id===id);
  if(!p) return;
  const mainArea = document.getElementById('pf-list').parentElement;
  let detail = document.getElementById('pf-detail');
  if(isGrid) {
    // Remove old overlay if exists
    let ov = document.getElementById('pf-overlay');
    if(!ov) {
      ov = document.createElement('div');
      ov.id = 'pf-overlay';
      ov.style.cssText = 'position:absolute;inset:0;background:#fff;z-index:10;overflow-y:auto;padding:14px;font-size:12px';
      mainArea.style.position = 'relative';
      mainArea.appendChild(ov);
    }
    detail = ov;
    detail.style.display = 'block';
  } else if(!detail) return;
  const lang = window._lang || 'en';
  const rich = projectRichContent[p.id];
  const richBody = rich ? rich[lang] || rich['en'] : null;
  detail.style.overflowY = 'auto';
  detail.innerHTML = `
    ${isGrid ? `<div style="margin-bottom:10px"><button class="win95-btn" onclick="pfCloseOverlay()">← Back</button></div>` : ''}
    <div style="display:flex;align-items:center;gap:10px;margin-bottom:10px;padding-bottom:8px;border-bottom:2px solid #c0c0c0">
      <span style="font-size:32px">${p.icon}</span>
      <div>
        <div style="font-size:14px;font-weight:bold">${t(p.titleKey)}</div>
        <div style="font-size:10px;color:#555;text-transform:uppercase;letter-spacing:1px;margin-top:2px">${p.cat}</div>
      </div>
    </div>
    ${richBody ? richBody : `<p style="margin:0 0 10px;line-height:1.7;font-size:12px">${t(p.descKey)}</p>`}
    <div style="margin-top:12px">
      <div style="font-size:10px;font-weight:bold;text-transform:uppercase;color:#555;margin-bottom:4px">Technologies</div>
      <div style="display:flex;flex-wrap:wrap;gap:4px">${p.tags.map(tg=>`<span class="tag" style="font-size:11px;padding:2px 6px">${tg}</span>`).join('')}</div>
    </div>`;
}




