function ping(args) {
  const host = args[0] || 'localhost';
  termPrint('out', `PING ${host}: 56 data bytes`);
  let i = 0;
  const times = [12, 8, 420, 3, 1337, 9, 5];
  const iv = setInterval(() => {
    const ms = times[i % times.length];
    const extra = ms === 420 ? ' (nice)' : ms === 1337 ? ' (elite)' : '';
    termPrint('out', `64 bytes from ${host}: icmp_seq=${i} ttl=64 time=${ms} ms${extra}`);
    i++;
    if (i >= 5) {
      clearInterval(iv);
      termPrint('out', '');
      termPrint('out', `--- ${host} ping statistics ---`);
      termPrint('out', `5 packets transmitted, 5 received, 0% packet loss`);
      termPrint('out', `round-trip min/avg/max = 3/357.8/1337 ms`);
      termNewLine();
    }
  }, 300);
}

function curl(args) {
  const url = args[args.length - 1];
  if (!url || url.startsWith('-')) { termPrint('err', 'curl: no URL specified'); return; }
  termPrint('out', `  % Total    % Received % Xferd  Speed   Time`);
  termPrint('out', `100   200  100   200    0     0   4200      0 --:--:-- --:--:--`);
  termPrint('out', '');
  if (url.includes('weather')) {
    termPrint('out', '  It\'s always sunny in yanyanOS. (18°C, feels like caffeine)');
  } else if (url.includes('localhost')) {
    termPrint('err', 'curl: (7) Failed to connect: port 3000: Connection refused');
    termPrint('warn', 'Did you forget to npm start again?');
  } else {
    termPrint('out', '<!DOCTYPE html>');
    termPrint('out', '<html><head><title>Access Denied</title></head>');
    termPrint('out', '<body>This is a fake terminal. No actual requests were made.</body>');
    termPrint('out', '</html>');
  }
}

