// 
// TRAY — WiFi & Battery pixel art
// 
let wifiStrength = 3;   // 0-3 bars
let batteryLevel = 69;  // percent (always 69, obviously)
let batteryCharging = false;

function drawWifi() {
  const c = document.getElementById('wifi-canvas');
  if (!c) return;
  const ctx = c.getContext('2d');
  ctx.clearRect(0,0,16,16);
  const bars = wifiStrength;
  // Draw 3 arcs, filled based on strength
  const cx = 8, cy = 14;
  const radii = [[3,5],[6,8],[9,11]];
  radii.forEach(([r1,r2],i) => {
    ctx.beginPath();
    ctx.arc(cx,cy,r2,Math.PI*1.2,Math.PI*1.8);
    ctx.arc(cx,cy,r1,Math.PI*1.8,Math.PI*1.2,true);
    ctx.closePath();
    ctx.fillStyle = (i < bars) ? '#000080' : '#aaaaaa';
    ctx.fill();
  });
  // Dot at base
  ctx.beginPath();
  ctx.arc(cx,cy,1.2,0,Math.PI*2);
  ctx.fillStyle = bars > 0 ? '#000080' : '#aaa';
  ctx.fill();
}

function drawBattery() {
  const c = document.getElementById('bat-canvas');
  if (!c) return;
  const ctx = c.getContext('2d');
  ctx.clearRect(0,0,20,12);
  // Battery body
  ctx.strokeStyle = '#333';
  ctx.lineWidth = 1;
  ctx.strokeRect(0.5,1.5,16,9);
  // Battery tip
  ctx.fillStyle = '#333';
  ctx.fillRect(17,4,2.5,4);
  // Fill
  const fillW = Math.round((batteryLevel/100)*14);
  ctx.fillStyle = batteryLevel > 20 ? (batteryCharging ? '#00aa00' : '#000080') : '#cc0000';
  ctx.fillRect(1.5,2.5,fillW,7);
  // Charging bolt
  if (batteryCharging) {
    ctx.fillStyle = '#fff';
    ctx.font = 'bold 8px sans-serif';
    ctx.fillText('',3,10);
  }
}

function showTrayPopup(type) {
  const tip = document.getElementById('tray-tooltip');
  const el = document.getElementById(type === 'wifi' ? 'tray-wifi' : 'tray-bat');
  if (!el || !tip) return;
  const rect = el.getBoundingClientRect();
  if (type === 'wifi') {
    const names = ['No network','yanyanOS-WiFi (weak)','yanyanOS-WiFi','yanyanOS-WiFi (excellent)'];
    tip.textContent = ` ${names[wifiStrength]}  —  Speed: ${[0,12,54,300][wifiStrength]} Mbps`;
  } else {
    tip.textContent = ` Battery: ${batteryLevel}% ${batteryCharging?'(Charging )':''}  —  Est. ${Math.round(batteryLevel*1.2)} min remaining`;
  }
  tip.style.display = 'block';
  tip.style.bottom = '42px';
  tip.style.right  = (window.innerWidth - rect.right + 4) + 'px';
  clearTimeout(tip._tid);
  tip._tid = setTimeout(() => tip.style.display='none', 2500);
}

function initTray() {
  drawWifi();
  drawBattery();
  // Simulate occasional wifi fluctuation
  setInterval(() => {
    if (Math.random() < 0.05) {
      wifiStrength = Math.max(1, Math.min(3, wifiStrength + (Math.random()>.5?1:-1)));
      drawWifi();
    }
    // Battery slowly drains (very slowly for comedy)
    if (!batteryCharging && Math.random() < 0.02) {
      batteryLevel = Math.max(1, batteryLevel - 1);
      drawBattery();
      if (batteryLevel <= 20) {
        showNotification({sound:false, icon:'', title:'Power Management', sender:'yanyanOS Battery',
          msg:`Battery low: ${batteryLevel}%\nPlease connect to power.\n(or just vibe, it's fine)`, duration:5000});
      }
    }
  }, 3000);
}

