function drawAboutOsLogo() {
  const c = document.getElementById('about-os-logo-canvas');
  if (!c) return;
  const ctx = c.getContext('2d');
  const S = 4;
  // Simple pixel OS logo — monitor with smiley
  ctx.fillStyle = '#000080';
  ctx.fillRect(0,0,64,64);
  // Monitor frame
  ctx.fillStyle = '#c0c0c0';
  ctx.fillRect(4,4,56,44);
  ctx.fillStyle = '#000080';
  ctx.fillRect(8,8,48,36);
  // Screen content
  ctx.fillStyle = '#00ff41';
  ctx.font = 'bold 18px VT323,monospace';
  ctx.fillText('yOS',12,32);
  // Stand
  ctx.fillStyle = '#c0c0c0';
  ctx.fillRect(22,48,20,6);
  ctx.fillRect(16,54,32,4);
  // Decorative pixel stars
  [[2,50],[58,50],[2,58],[58,2],[2,2]].forEach(([x,y])=>{
    ctx.fillStyle = '#ffff00';
    ctx.fillRect(x,y,3,3);
  });
}

