let notifQueue = [];
let notifShowing = false;

function playYouveGotMail() {
  try {
    const ctx = new (window.AudioContext || window.webkitAudioContext)();
    // Cheerful 3-note ding melody: E5 G5 C6
    const notes = [{f:659,t:0,d:.12},{f:784,t:.13,d:.12},{f:1047,t:.27,d:.22}];
    notes.forEach(({f,t,d}) => {
      const o = ctx.createOscillator();
      const g = ctx.createGain();
      o.connect(g); g.connect(ctx.destination);
      o.type = 'sine'; o.frequency.value = f;
      const start = ctx.currentTime + t;
      g.gain.setValueAtTime(0, start);
      g.gain.linearRampToValueAtTime(0.18, start + 0.01);
      g.gain.exponentialRampToValueAtTime(0.001, start + d);
      o.start(start); o.stop(start + d + 0.05);
    });
  } catch(e) {}
}

function showNotification(opts) {
  // opts: { icon, sender, msg, duration }
  if (opts.sound !== false) playYouveGotMail();
  const container = document.getElementById('notif-container');
  const toast = document.createElement('div');
  toast.className = 'notif-toast';
  const dur = opts.duration || 15000;
  toast.innerHTML = `
    <div class="notif-titlebar">
      <span class="notif-icon">${opts.icon || ''}</span>
      <span style="flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${opts.title || 'New Message'}</span>
      <div class="notif-close" onclick="dismissToast(this.closest('.notif-toast'))">✕</div>
    </div>
    <div class="notif-body">
      <div class="notif-sender">${opts.sender || ''}</div>
      <div>${opts.msg.replace(/\n/g,'<br>')}</div>
    </div>
    <div class="notif-progress" style="animation-duration:${dur}ms"></div>`;

  container.appendChild(toast);

  // Pulse tray dot
  const dot = document.getElementById('tray-notif-dot');
  dot.style.display = 'block';

  // Auto-dismiss
  const tid = setTimeout(() => dismissToast(toast), dur);
  toast._tid = tid;
}

function dismissToast(toast) {
  if (!toast || toast._dismissed) return;
  toast._dismissed = true;
  clearTimeout(toast._tid);
  toast.classList.add('hiding');
  setTimeout(() => {
    toast.remove();
    // Hide tray dot if no more toasts
    if (!document.getElementById('notif-container').children.length) {
      document.getElementById('tray-notif-dot').style.display = 'none';
    }
  }, 320);
}

function scheduleRecruiterNotif() {
  // First one fires between 20-40s after boot, then randomly every 2-5 min
  const delay = 20000 + Math.random() * 20000;
  setTimeout(function fire() {
    const rec = recruiterMessages[Math.floor(Math.random() * recruiterMessages.length)];
    showNotification({
      icon: '',
      title: 'Yanyan Mail — New Message',
      sender: rec.sender,
      msg: rec.msg,
      duration: 9000
    });
    // Schedule next: 2–5 minutes
    setTimeout(fire, 120000 + Math.random() * 180000);
  }, delay);
}

// 
// BSOD  —  rare: ~3% chance every 3 minutes
// 

const bsodJokes = [
  `bro really thought the portfolio crashed.\n\nnah relax it's just a bit.`,
  `skill issue detected.\n\njust kidding. the OS is fine. you got baited.`,
  `imagine panicking over a fake BSOD.\n\nthis portfolio is just trolling you.`,
  `congratulations.\n\nyou unlocked the hidden "touch grass" error screen.`,
  `system failure.\n\njust kidding.\n\nthat was emotional damage.`,
  `critical error:\nrecruiter.exe used 100% of available RAM.`,
  `if you panicked for even half a second…\n\nmission accomplished.`,
  `windows 95 called.\n\nit wants its crash screen back.`,
  `calm down.\n\nnothing broke.\n\nthis portfolio just likes causing mild psychological distress.`,
  `rare event unlocked:\nvisitor.exe successfully trolled haaaaaaaaaaa.`,
];

let bsodBlinkInterval = null;

function triggerBSOD() {
  const bsod = document.getElementById('bsod');
  const joke = bsodJokes[Math.floor(Math.random() * bsodJokes.length)];
  document.getElementById('bsod-joke').innerText = joke;
  bsod.classList.add('active');

  // Blinking cursor
  let on = true;
  bsodBlinkInterval = setInterval(() => {
    const el = document.getElementById('bsod-blink');
    if (el) { el.style.visibility = on ? 'visible' : 'hidden'; on = !on; }
  }, 500);

  // Dismiss on any key or OK button
  const dismiss = () => dismissBSOD();
  document.addEventListener('keydown', dismiss, { once: true });
  document.getElementById('bsod-ok-btn').onclick = dismiss;
}

function dismissBSOD() {
  clearInterval(bsodBlinkInterval);
  const bsod = document.getElementById('bsod');
  bsod.style.transition = 'opacity .4s';
  bsod.style.opacity = '0';
  setTimeout(() => {
    bsod.classList.remove('active');
    bsod.style.opacity = '';
    bsod.style.transition = '';
  }, 400);
  scheduleBSOD();
}

function scheduleBSOD() {
  // Check every 3 minutes, 3% chance of firing
  setTimeout(function check() {
    if (Math.random() < 0.03) {
      triggerBSOD();
    } else {
      setTimeout(check, 180000); // try again in 3 min
    }
  }, 180000);
}

